//! u0ui Gallery: every component, live, in all four Carbon themes.
//!
//! ```text
//! cargo run -p u0ui-gallery -- [--page <id>] [--theme <white|g10|g90|g100>]
//!     [--density <compact|comfortable>] [--capture <dir> [--size 1440x900]]
//! ```
//!
//! `--page` takes `home`, `overview`, `foundations`, `components`, `patterns`
//! or a page id. `--capture <dir>` renders that route (or, without `--page`,
//! every route) to `<dir>/<id>-<theme>.png` in a hidden window and exits.
mod capture;
mod controls;
/// Sources generated by `u0ui-codegen` from the design reference; do not edit.
mod generated {
    /// Every reference component and its README summary.
    #[allow(dead_code)] // `ALL` and `name` are for pages yet to come.
    pub mod descriptions {
        include!("generated/descriptions.rs");
    }
}
mod home;
mod overview;
mod page;
mod pages;
mod registry;
mod shell;
mod specs;
mod stand_in;
mod thumbnails;
mod top_bar;

use gpui_kit::*;
use shell::Route;
use u0ui::CarbonTheme;

const USAGE: &str = "usage: gallery [--page <id>] [--theme <white|g10|g90|g100>] \
[--density <compact|comfortable>] [--capture <dir> [--size <width>x<height>]]";

/// Parsed command line.
#[derive(Default)]
struct Args {
    page: Option<Route>,
    theme: Option<CarbonTheme>,
    density: Option<u0ui::Density>,
    capture: Option<std::path::PathBuf>,
    size: Option<(f32, f32)>,
}

fn route_ids() -> String {
    let mut ids = vec!["home", "overview", "foundations", "components", "patterns"];
    ids.extend(registry::PAGES.iter().map(|p| p.id));
    ids.join(", ")
}

fn parse_args() -> anyhow::Result<Args> {
    let mut args = Args::default();
    let mut it = std::env::args().skip(1);
    while let Some(arg) = it.next() {
        let mut value = |name: &str| {
            it.next()
                .ok_or_else(|| anyhow::anyhow!("{name} needs a value\n{USAGE}"))
        };
        match arg.as_str() {
            "--page" => {
                let id = value("--page")?;
                args.page = Some(Route::from_id(&id).ok_or_else(|| {
                    anyhow::anyhow!("unknown page {id:?}; pages: {}", route_ids())
                })?);
            }
            "--theme" => {
                let id = value("--theme")?;
                args.theme = Some(
                    CarbonTheme::from_id(&id)
                        .ok_or_else(|| anyhow::anyhow!("unknown theme {id:?}\n{USAGE}"))?,
                );
            }
            "--density" => {
                let id = value("--density")?;
                args.density = Some(
                    u0ui::Density::ALL
                        .into_iter()
                        .find(|d| d.id() == id)
                        .ok_or_else(|| anyhow::anyhow!("unknown density {id:?}\n{USAGE}"))?,
                );
            }
            "--capture" => args.capture = Some(value("--capture")?.into()),
            "--size" => {
                let size = value("--size")?;
                let (w, h) = size
                    .split_once('x')
                    .and_then(|(w, h)| Some((w.parse().ok()?, h.parse().ok()?)))
                    .ok_or_else(|| anyhow::anyhow!("--size takes <width>x<height>\n{USAGE}"))?;
                args.size = Some((w, h));
            }
            "--help" | "-h" => {
                println!("{USAGE}\n\npages: {}", route_ids());
                std::process::exit(0);
            }
            other => anyhow::bail!("unexpected argument {other:?}\n{USAGE}"),
        }
    }
    Ok(args)
}

fn main() -> anyhow::Result<()> {
    let args = parse_args()?;
    gpui_kit::application()
        .with_assets(u0ui::Assets::new())
        .run(move |cx: &mut App| {
            gpui_kit::init(cx);
            if let Some(theme) = args.theme {
                cx.set_global(u0ui::theme::ActiveTheme(theme));
            }
            u0ui::init(cx);
            shell::bind_keys(cx);
            if let Some(density) = args.density {
                u0ui::density::set_density(cx, density);
            }
            let capture = args.capture.clone().map(|dir| capture::Capture {
                dir,
                routes: match args.page {
                    Some(route) => vec![route],
                    None => [Route::Home, Route::Overview(None)]
                        .into_iter()
                        .chain((0..registry::PAGES.len()).map(Route::Page))
                        .collect(),
                },
                suffix: u0ui::theme::current().id().to_string(),
            });
            let (width, height) = args.size.unwrap_or(if capture.is_some() {
                (1440., 900.)
            } else {
                (1280., 820.)
            });
            let bounds = Bounds::centered(None, size(px(width), px(height)), cx);
            let options = WindowOptions {
                window_bounds: Some(WindowBounds::Windowed(bounds)),
                // `window-min-width` × `window-min-height`.
                window_min_size: Some(size(
                    u0ui::tokens::WINDOW_MIN_WIDTH.pixels(),
                    u0ui::tokens::WINDOW_MIN_HEIGHT.pixels(),
                )),
                titlebar: Some(TitlebarOptions {
                    title: Some("u0ui Gallery".into()),
                    ..Default::default()
                }),
                show: capture.is_none(),
                focus: capture.is_none(),
                ..Default::default()
            };
            let route = args.page.unwrap_or(Route::Home);
            gpui_kit::open_window(options, cx, move |window, cx| {
                let gallery = cx.new(|cx| shell::Gallery::new(route, window, cx));
                if let Some(capture) = capture {
                    capture::start(capture, gallery.clone(), window, cx);
                }
                gallery
            })
            .expect("failed to open the gallery window");
            if args.capture.is_none() {
                cx.activate(true);
            }
        });
    Ok(())
}
